/* voyager.chatgpt-reading-width — one wider, centered reading column.
 * ChatGPT sizes every conversation turn (and the composer) from the CSS var
 * --thread-content-max-width (48rem / 768px), consumed via Tailwind
 * max-w-(--thread-content-max-width). Raising both the variable and the
 * resolved max-width on those containers widens the column; they are mx-auto,
 * so they stay centered. The slider drives {{width}} (px). */
.gv-plugin-chatgpt-readable [class*="--thread-content-max-width"] {
  --thread-content-max-width: {{width}}px !important;
  max-width: {{width}}px !important;
}
